package com.roadwatch.report;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class PotholeReport { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; private double latitude; private double longitude; private String authority; private String evidenceUrl; private String storageKey; private double confidence; @Enumerated(EnumType.STRING) private Severity severity; @Enumerated(EnumType.STRING) private ReportStatus status=ReportStatus.REPORTED; private Instant capturedAt; private Instant createdAt=Instant.now(); public String getId(){return id;} public double getLatitude(){return latitude;} public void setLatitude(double v){latitude=v;} public double getLongitude(){return longitude;} public void setLongitude(double v){longitude=v;} public String getAuthority(){return authority;} public void setAuthority(String v){authority=v;} public String getEvidenceUrl(){return evidenceUrl;} public void setEvidenceUrl(String v){evidenceUrl=v;} public String getStorageKey(){return storageKey;} public void setStorageKey(String v){storageKey=v;} public double getConfidence(){return confidence;} public void setConfidence(double v){confidence=v;} public Severity getSeverity(){return severity;} public void setSeverity(Severity v){severity=v;} public ReportStatus getStatus(){return status;} public void setStatus(ReportStatus v){status=v;} public Instant getCapturedAt(){return capturedAt;} public void setCapturedAt(Instant v){capturedAt=v;} }
